import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        CountDownLatch ready = new CountDownLatch(3);
        for (int i = 0; i < 3; i++) {
            new Thread(() -> ready.countDown(), "w" + i).start();
        }
        ready.await();
        System.out.println("CountDownLatch count after all ready = " + ready.getCount());

        AtomicInteger phases = new AtomicInteger();
        CyclicBarrier barrier = new CyclicBarrier(3, () -> phases.incrementAndGet());
        Runnable phaseTask = () -> {
            try { for (int p = 1; p <= 2; p++) barrier.await(); }
            catch (Exception e) { Thread.currentThread().interrupt(); }
        };
        Thread[] ts = new Thread[3];
        for (int i = 0; i < 3; i++) { ts[i] = new Thread(phaseTask); ts[i].start(); }
        for (Thread t : ts) t.join(5000L);
        System.out.println("CyclicBarrier phases reached         = " + phases.get());

        Semaphore sem = new Semaphore(3);
        sem.acquire(3);
        System.out.println("Semaphore permits after acquire(3)   = " + sem.availablePermits());
        System.out.println("Semaphore tryAcquire() with 0 left   = " + sem.tryAcquire());
        sem.release(3);
        System.out.println("Semaphore permits after release(3)   = " + sem.availablePermits());
    }
}
